package com.corecs.persistence.controller;import com.corecs.persistence.model.SavedQuery;import com.corecs.persistence.repository.SavedQueryRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/saved-queries") public class SavedQueryController{private final SavedQueryRepository repo;public SavedQueryController(SavedQueryRepository r){repo=r;}public record Request(@NotBlank String name,@NotBlank String sql){}@GetMapping public List<SavedQuery> all(){return repo.findAll();}@PostMapping public SavedQuery save(@Valid @RequestBody Request r){return repo.save(new SavedQuery(r.name(),r.sql()));}@DeleteMapping("/{id}")public void delete(@PathVariable Long id){repo.deleteById(id);}}
